mapper.select:
SELECT m.id, m.name, m.type, m.specification, m.unit, m.total_quantity, m.warning_quantity, m.moisture_proof, m.status, b.id AS batch_id, b.batch_code, b.quantity AS batch_quantity, b.unit_price, b.supplier, b.production_date, b.expiry_date, b.warehouse_area, b.humidity, b.moisture_warning, b.status AS batch_status FROM raw_material m LEFT JOIN raw_material_batch b ON m.id = b.material_id AND b.status = 1 AND b.quantity > 0
m.deleted = 0
AND m.type = #{type}
AND m.status = #{status}
AND (m.name LIKE CONCAT('%', #{keyword}, '%') OR m.specification LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY m.create_time DESC, b.production_date ASC

SELECT m.name AS material_name, m.type, SUM(CASE WHEN b.status = 1 THEN b.quantity ELSE 0 END) AS available_quantity, SUM(CASE WHEN b.status = 0 THEN b.quantity ELSE 0 END) AS used_quantity, COUNT(b.id) AS batch_count, SUM(CASE WHEN b.moisture_warning = 1 THEN 1 ELSE 0 END) AS moisture_warning_count FROM raw_material m LEFT JOIN raw_material_batch b ON m.id = b.material_id WHERE m.deleted = 0 AND b.deleted = 0
AND b.create_time >= #{startDate}
AND b.create_time <= #{endDate}
GROUP BY m.id, m.name, m.type ORDER BY available_quantity DESC
